{
  "status": "SUPPORTED",
  "task_summary": "Prepare the living room for two people to enjoy refreshments while watching television. Provide each person with their own refreshment setting nearby, and place the entertainment control where it is accessible to both people.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_item",
        "entity_kind": "OBJECT",
        "function": "Hold or serve food or drink for a person.",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      , "candidate_categories": ["cup", "plate", "mug", "snack"],
        "required_properties": ["holds_refreshment", "portable"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "controller", "button_panel"],
        "required_properties": ["operates_television"]
      },
      {
        "id": "seating_spot",
        "entity_kind": "REGION",
        "function": "Area where a person sits to watch television.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["chair", "couch", "sofa"],
        "required_properties": ["supports_person", "facing_television"]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Display video content for viewing.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tv", "screen", "monitor"],
        "required_properties": ["displays_video", "receives_signals"]
      },
      {
        "id": "accessible_surface",
        "entity_kind": "REGION",
        "function": "Flat area where the entertainment control is placed for access.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "side_table", "ottoman"],
        "required_properties": ["flat", "reachable_from_seating"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_placement",
        "relation": "Each refreshment item is placed near its corresponding seating spot.",
        "participant_roles": ["refreshment_item", "seating_spot"]
      , "required": true
      },
      {
        "id": "control_accessibility",
        "relation": "The accessible surface is reachable from both seating spots.",
        "participant_roles": ["accessible_surface", "seating_spot"]
      , "required": true
      },
      {
        "id": "operation_link",
        "relation": "The entertainment control operates the television.",
        "participant_roles": ["entertainment_control", "television"]
      , "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "setup_refreshment",
        "operation": "Move refreshment items to seating spots.",
        "participant_roles": ["refreshment_item", "seating_spot"],
        "operation_count": 2
      },
      {
        "id": "move_remote",
        "operation": "Move entertainment control to accessible surface.",
        "participant_roles": ["entertainment_control", "accessible_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_item": [
        {
          "label": "cups and plate on the desk in the foreground",
          "visual_description": "Two red cups and a white plate visible on the wooden desk in the foreground."
        }
      ],
      "entertainment_control": [
        {
          "label": "remote on the desk in the foreground",
          "visual_description": "A black remote control visible on the wooden desk in the foreground."
        }
      ],
      "seating_spot": [
        {
          "label": "left armchair",
          "visual_description": "A wooden armchair with black cushion on the left side."
        },
        {
          "label": "right armchair",
          "visual_description": "A wooden armchair with black cushion on the right side."
        }
      ],
      "accessible_surface": [
        {
          "label": "side tables next to chairs",
          "visual_description": "Small wooden tables located beside each armchair."
        },
        {
          "label": "coffee table in the center",
          "visual_description": "A rectangular table with a light top in the middle of the seating arrangement."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_in_foreground",
        "label": "desk in the foreground",
        "visual_description": "Large wooden desk containing cups, remote, and plate.",
        "reason": "Contains the visible refreshment items and entertainment control; may hold additional items or be the source for moving items."
      },
      {
        "id": "console_table",
        "label": "console table under television",
        "visual_description": "Narrow wooden table mounted against the wall under the TV.",
        "reason": "Located near the television; could contain the entertainment control or other media devices."
      },
      {
        "id": "side_tables",
        "label": "side tables next to chairs",
        "visual_description": "Two small wooden tables flanking the armchairs.",
        "reason": "Potential destinations for refreshment settings; one currently holds a plate."
      }
    ],
    "inspection_order": [
      "desk_in_foreground",
      "console_table",
      "side_tables"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
